package com.controldecortes.controller;
import com.controldecortes.dto.ApiDtos.SettlementResponse; import com.controldecortes.service.SettlementService; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/reports") public class ReportController {
 private final SettlementService service; public ReportController(SettlementService s){service=s;}
 @GetMapping("/settlements") public List<SettlementResponse> settlements(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.report(from.atStartOfDay().atOffset(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC));}
 @GetMapping(value="/settlements.csv",produces="text/csv") public ResponseEntity<String> csvReport(@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=faturamentos-"+from+"-"+to+".csv").body(service.reportCsv(from.atStartOfDay().atOffset(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC)));}
 @GetMapping("/monthly/{year}/{month}") public List<SettlementResponse> monthly(@PathVariable int year,@PathVariable int month){YearMonth ym=YearMonth.of(year,month);return service.report(ym.atDay(1).atStartOfDay().atOffset(ZoneOffset.UTC),ym.plusMonths(1).atDay(1).atStartOfDay().atOffset(ZoneOffset.UTC));}
 @GetMapping("/annual/{year}") public List<SettlementResponse> annual(@PathVariable int year){LocalDate start=LocalDate.of(year,1,1);return service.report(start.atStartOfDay().atOffset(ZoneOffset.UTC),start.plusYears(1).atStartOfDay().atOffset(ZoneOffset.UTC));}
 @GetMapping(value="/monthly/{year}/{month}/csv",produces="text/csv") public ResponseEntity<String> monthlyCsv(@PathVariable int year,@PathVariable int month){YearMonth ym=YearMonth.of(year,month);return csv(ym.atDay(1),ym.plusMonths(1).atDay(1));}
 @GetMapping(value="/annual/{year}/csv",produces="text/csv") public ResponseEntity<String> annualCsv(@PathVariable int year){LocalDate start=LocalDate.of(year,1,1);return csv(start,start.plusYears(1));}
 private ResponseEntity<String> csv(LocalDate from,LocalDate exclusiveTo){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=faturamentos-"+from+".csv").body(service.reportCsv(from.atStartOfDay().atOffset(ZoneOffset.UTC),exclusiveTo.atStartOfDay().atOffset(ZoneOffset.UTC)));}
}
